// How the UI words an alert's data flags (contracts/C4-alert.md "Wording class and data flags").
// The API adds no wording to an alert; the UI words it from these two booleans.

export interface AlertDataFlags {
  involves_real_entities: boolean
  synthetic_activity: boolean
}

export type AlertDataLabel =
  { kind: 'synthetic' } | { kind: 'synthetic_activity'; text: string } | { kind: 'none' }

export const SYNTHETIC_ACTIVITY_TEXT =
  'This pattern lies in synthetic background activity generated by NeonRadar.'

/**
 * Every entity synthetic: a "Synthetic" badge. A real entity with only generated relationships
 * in the evidence: say that the pattern lies in synthetic background activity.
 */
export function alertDataLabel(flags: AlertDataFlags): AlertDataLabel {
  if (!flags.involves_real_entities) return { kind: 'synthetic' }
  if (flags.synthetic_activity) return { kind: 'synthetic_activity', text: SYNTHETIC_ACTIVITY_TEXT }
  return { kind: 'none' }
}

export const PRIORITIES = ['high', 'medium', 'low'] as const
